import {NextResponse} from 'next/server';
import {getSupabaseServer,requireUser} from '../../../../lib/supabase/server';
export const runtime='nodejs';
function isAdmin(user){return user?.app_metadata?.role==='admin'}
async function guard(request){const user=await requireUser(request);if(!isAdmin(user))throw new Error('Forbidden');return user}
export async function GET(request){try{await guard(request);const db=getSupabaseServer();const{data,error}=await db.from('vendors').select('id,name,description,contact_email,phone,address,status,created_at,approved_at,approved_by,rejection_reason').order('created_at',{ascending:false});if(error)throw error;return NextResponse.json({vendors:data||[]})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message==='Forbidden'?'Admin access required.':'Unable to load vendor applications.'},{status:e.message==='Unauthorized'?401:e.message==='Forbidden'?403:500})}}
export async function PATCH(request){try{const admin=await guard(request);const b=await request.json();const allowed=['Active','Rejected','Suspended','Pending'];if(!b.vendor_id||!allowed.includes(b.status))return NextResponse.json({error:'A valid vendor_id and status are required.'},{status:400});if(b.status==='Rejected'&&!String(b.rejection_reason||'').trim())return NextResponse.json({error:'A rejection reason is required.'},{status:400});const db=getSupabaseServer();const patch={status:b.status,rejection_reason:b.status==='Rejected'?String(b.rejection_reason).trim():null,approved_at:b.status==='Active'?new Date().toISOString():null,approved_by:b.status==='Active'?admin.id:null};const{data,error}=await db.from('vendors').update(patch).eq('id',b.vendor_id).select('id,name,status,approved_at,approved_by,rejection_reason').single();if(error)throw error;return NextResponse.json({vendor:data})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message==='Forbidden'?'Admin access required.':e.message||'Vendor approval failed.'},{status:e.message==='Unauthorized'?401:e.message==='Forbidden'?403:400})}}
